 "Mathematik (# min, ohne Taschenrechner): Grundoperationen und Kopfrechnen, Brüche/Dezimalzahlen, Masseinheiten umrechnen, Proportionalität und Dreisatz, Geometrie (Flächen, Umfang, Winkel, Körper, Konstruktion beschreiben), Knobel- und Textaufgaben aus dem Alltag. Lösungsweg gibt Teilpunkte. Viele mehrteilige Aufgaben mit steigender Schwierigkeit.": "Matematica (# min, senza calcolatrice): operazioni di base e calcolo mentale, frazioni/decimali, conversione unità, proporzionalità e proporzioni, geometria (aree, perimetri, angoli, solidi, descrizione costruzioni), problemi di logica e testi quotidiani. La soluzione dà punti parziali. Molti esercizi a più parti con difficoltà crescente.",
 "Mathematik Matura: Analysis (Ableitung, Kurvendiskussion, Integral, Extremalprobleme), Vektorgeometrie, Wahrscheinlichkeit/Kombinatorik, Folgen. Mehrteilige Aufgaben, vollständiger Lösungsweg.": "Matematica Maturità: Analisi (derivata, studio curve, integrale, problemi estremali), geometria vettoriale, probabilità/combinatoria, successioni. Esercizi a più parti, soluzione completa.",
